args.command:
# Try wallii.gg leaderboard page
curl -s 'https://www.wallii.gg/leaderboard' | grep -oP '__NEXT_DATA__[^<]*' | python3 -c "
import sys, json
data = sys.stdin.read()
if data:
    obj = json.loads(data)
    pp = obj.get('props',{}).get('pageProps',{})
    print(json.dumps(list(pp.keys()), indent=2))
    for k,v in pp.items():
        if isinstance(v, list) and len(v) > 0:
            print(f'{k}: {len(v)} items, first: {json.dumps(v[0])[:200]}')
        elif isinstance(v, dict):
            print(f'{k}: dict with keys {list(v.keys())[:10]}')
        else:
            print(f'{k}: {str(v)[:200]}')
" 2>/dev/null
